===== resolveByRegion.test.ts
     1	import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
     2	import { filterByRegion, pickMostSpecificByRegion } from './resolveByRegion';
     3	
     4	type Fixture = {
     5	  sys: { id: string; updatedAt?: string };
     6	  fields: { regions?: ReadonlyArray<{ fields: { siteId: string } }> };
     7	};
     8	
     9	const region = (siteId: string) => ({ fields: { siteId } });
    10	
    11	const entry = (id: string, siteIds?: string[], updatedAt?: string): Fixture => ({
    12	  sys: { id, updatedAt },
    13	  fields: { regions: siteIds ? siteIds.map(region) : undefined },
    14	});
    15	
    16	describe('filterByRegion', () => {
    17	  test('keeps a global (unscoped) entry for any site', () => {
    18	    const global = entry('global');
    19	    expect(filterByRegion([global], 'ZimmermannUS')).toEqual([global]);
    20	  });
    21	
    22	  test('keeps a global entry with an explicitly empty regions array', () => {
    23	    const global = entry('global', []);
    24	    expect(filterByRegion([global], 'ZimmermannUS')).toEqual([global]);
    25	  });
    26	
    27	  test('keeps an entry whose regions include the current site', () => {
    28	    const us = entry('us', ['ZimmermannUS']);
    29	    expect(filterByRegion([us], 'ZimmermannUS')).toEqual([us]);
    30	  });
    31	
    32	  test('drops an entry scoped to other sites only', () => {
    33	    const au = entry('au', ['ZimmermannAU']);
    34	    expect(filterByRegion([au], 'ZimmermannUS')).toEqual([]);
    35	  });
    36	
    37	  test('keeps multiple non-conflicting eligible entries', () => {
    38	    const global = entry('global');
    39	    const us = entry('us', ['ZimmermannUS']);
    40	    const au = entry('au', ['ZimmermannAU']);
    41	    expect(filterByRegion([global, us, au], 'ZimmermannUS')).toEqual([global, us]);
    42	  });
    43	});
    44	
    45	describe('pickMostSpecificByRegion', () => {
    46	  test('returns undefined when no candidates are eligible', () => {
    47	    const au = entry('au', ['ZimmermannAU']);
    48	    expect(pickMostSpecificByRegion([au], 'ZimmermannUS')).toBeUndefined();
    49	  });
    50	
    51	  test('returns the global fallback when no regional entry exists', () => {
    52	    const global = entry('global');
    53	    expect(pickMostSpecificByRegion([global], 'ZimmermannUS')).toBe(global);
    54	  });
    55	
    56	  test('a US-scoped override wins over a broader global entry', () => {
    57	    const global = entry('global');
    58	    const usOverride = entry('us-override', ['ZimmermannUS']);
    59	    expect(pickMostSpecificByRegion([global, usOverride], 'ZimmermannUS')).toBe(usOverride);
    60	  });
    61	
    62	  test('narrower regions array wins over a broader (but still eligible) one', () => {
    63	    const broad = entry('broad', ['ZimmermannUS', 'ZimmermannAU']);
    64	    const narrow = entry('narrow', ['ZimmermannUS']);
    65	    expect(pickMostSpecificByRegion([broad, narrow], 'ZimmermannUS')).toBe(narrow);
    66	  });
    67	
    68	  describe('tie-break', () => {
    69	    beforeEach(() => {
    70	      vi.spyOn(console, 'warn').mockImplementation(() => {});
    71	    });
    72	
    73	    afterEach(() => {
    74	      vi.restoreAllMocks();
    75	    });
    76	
    77	    test('two equally-scoped entries resolve to the most recently updated, and warn', () => {
    78	      const older = entry('older', ['ZimmermannUS'], '2026-01-01T00:00:00.000Z');
    79	      const newer = entry('newer', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
    80	      expect(pickMostSpecificByRegion([older, newer], 'ZimmermannUS')).toBe(newer);
    81	      expect(console.warn).toHaveBeenCalledTimes(1);
    82	    });
    83	
    84	    test('order of the tied candidates in the input does not change the outcome', () => {
    85	      const older = entry('older', ['ZimmermannUS'], '2026-01-01T00:00:00.000Z');
    86	      const newer = entry('newer', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
    87	      expect(pickMostSpecificByRegion([newer, older], 'ZimmermannUS')).toBe(newer);
    88	    });
    89	  });
    90	});

