===== bootstrapSpace.mjs
     1	#!/usr/bin/env node
     2	/**
     3	 * Bootstrap the Zimmermann Contentful space.
     4	 *
     5	 * Creates environments, locales, per-environment API keys, and the production
     6	 * alias for the six-tier delivery pipeline. Idempotent — safe to re-run.
     7	 *
     8	 * Tier topology:
     9	 *   DEV (dev) → TEST (test) → OMS INT (sit) → STAGE (staging) → UAT (uat) → PROD (master / production alias)
    10	 *
    11	 * Usage:
    12	 *   npm run setup:contentful
    13	 *   npm run setup:contentful -- --dry-run
    14	 *
    15	 * Required env vars (via .env):
    16	 *   CONTENTFUL_MANAGEMENT_TOKEN, CONTENTFUL_SPACE_ID
    17	 */
    18	
    19	import {
    20	  checkEnv,
    21	  createClient,
    22	  pollForReady,
    23	  getExistingEnvironmentIds,
    24	  getExistingLocaleCodes,
    25	  log,
    26	} from './_shared.mjs';
    27	
    28	const DRY_RUN = process.argv.includes('--dry-run');
    29	
    30	if (DRY_RUN) console.log('\n🔍  DRY RUN — no changes will be made.\n');
    31	
    32	checkEnv(['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_SPACE_ID']);
    33	
    34	// Environments to create, cloned from master.
    35	// master is created automatically by Contentful.
    36	const TARGET_ENVIRONMENTS = ['dev', 'test', 'sit', 'staging', 'uat'];
    37	
    38	// Locales — codes match SFCC sites.js locale IDs exactly so no mapping is needed.
    39	// en (AU) is the default/fallback; all others fall back to en.
    40	const LOCALES = [
    41	  { code: 'en',    name: 'English (AU)',             default: true,  fallbackCode: null  },
    42	  { code: 'en-US', name: 'English (US)',              default: false, fallbackCode: 'en' },
    43	  { code: 'en-GB', name: 'English (UK / EU)',         default: false, fallbackCode: 'en' },
    44	  { code: 'fr',    name: 'French (EU)',               default: false, fallbackCode: 'en' },
    45	  { code: 'it',    name: 'Italian (EU)',              default: false, fallbackCode: 'en' },
    46	  { code: 'es',    name: 'Spanish (EU)',              default: false, fallbackCode: 'en' },
    47	  { code: 'en-CH', name: 'English (EU International)', default: false, fallbackCode: 'en' },
    48	  { code: 'en-HK', name: 'English (HK)',              default: false, fallbackCode: 'en' },
    49	  { code: 'en-AE', name: 'English (ME)',              default: false, fallbackCode: 'en' },
    50	];
    51	
    52	// Aliases to create/maintain.
    53	// production alias is what the MRT production tier points to — flipping it
    54	// is the zero-downtime release mechanism. master is kept in sync with it.
    55	const ALIASES = ['production'];
    56	
    57	const results = {
    58	  environments: { created: [], skipped: [] },
    59	  locales: { created: [], skipped: [], failed: [] },
    60	  apiKeys: { created: [], skipped: [] },
    61	  aliases: { created: [], updated: [], skipped: [] },
    62	};
    63	
    64	async function main() {
    65	  const client = createClient();
    66	
    67	  // ── 1. Environments ─────────────────────────────────────────────────────────
    68	  log.section('Environments');
    69	
    70	  const { items: envItems } = await client.environment.getMany({ query: { limit: 100 } });
    71	  const existingById   = new Map(envItems.map((e) => [e.sys.id, e]));
    72	  const existingByName = new Map(envItems.map((e) => [e.name,   e]));
    73	  log.info(`Existing: ${[...existingById.keys()].join(', ')}`);
    74	
    75	  for (const envId of TARGET_ENVIRONMENTS) {
    76	    if (existingById.has(envId)) {
    77	      log.skip(`Environment '${envId}' already exists`);
    78	      results.environments.skipped.push(envId);
    79	      continue;
    80	    }
    81	    // An environment with this name exists but was created with a wrong auto-generated ID
    82	    // (can happen if a previous run failed mid-way using create() instead of createWithId())
    83	    if (existingByName.has(envId)) {
    84	      const orphan = existingByName.get(envId);
    85	      log.warn(`Environment named '${envId}' exists with ID '${orphan.sys.id}'. Delete it in the Contentful web UI then re-run.`);
    86	      results.environments.skipped.push(envId);
    87	      continue;
    88	    }
    89	    if (DRY_RUN) {
    90	      log.info(`[dry-run] Would create environment '${envId}' (clone of master)`);
    91	      results.environments.created.push(envId);
    92	      continue;
    93	    }
    94	    log.info(`Creating environment '${envId}' (cloning from master)...`);
    95	    // createWithId ensures the environment's API ID matches its name (e.g. 'dev' → ID 'dev')
    96	    await client.environment.createWithId({ environmentId: envId }, { name: envId }, 'master');
    97	    process.stdout.write('  Waiting for ready');
    98	    await pollForReady(client, envId);
    99	    console.log();
   100	    log.success(`Environment '${envId}' ready`);
   101	    results.environments.created.push(envId);
   102	  }
   103	
   104	  // ── 2. Locales (set up in master; cloned environments inherit them) ─────────
   105	  log.section('Locales');
   106	
   107	  const existingLocales = await getExistingLocaleCodes(client, 'master');
   108	  log.info(`Existing locales in master: ${existingLocales.join(', ')}`);
   109	
   110	  for (const locale of LOCALES) {
   111	    if (existingLocales.includes(locale.code)) {
   112	      log.skip(`Locale '${locale.code}' already exists`);
   113	      results.locales.skipped.push(locale.code);
   114	      continue;
   115	    }
   116	    if (DRY_RUN) {
   117	      log.info(`[dry-run] Would create locale '${locale.code}' (${locale.name})`);
   118	      results.locales.created.push(locale.code);
   119	      continue;
   120	    }
   121	    const payload = {
   122	      name: locale.name,
   123	      code: locale.code,
   124	      default: locale.default,
   125	      // Non-default locales are optional: required-localized fields can publish with
   126	      // only 'en' set — translation is a separate, later pass through the translation
   127	      // app, not a precondition for publishing English content. fallbackCode above
   128	      // covers reads in the meantime.
   129	      optional: !locale.default,
   130	    };
   131	    if (locale.fallbackCode) payload.fallbackCode = locale.fallbackCode;
   132	
   133	    try {
   134	      await client.locale.create({ environmentId: 'master' }, payload);
   135	      log.success(`Created locale '${locale.code}' (${locale.name})`);
   136	      results.locales.created.push(locale.code);
   137	    } catch (err) {
   138	      log.warn(`Failed to create locale '${locale.code}': ${err.message ?? err}. Skipping — re-run later to retry.`);
   139	      results.locales.failed.push(locale.code);
   140	    }
   141	  }
   142	
   143	  // ── 3. Per-environment API keys (Delivery + Preview) ────────────────────────
   144	  log.section('API Keys');
   145	
   146	  const { items: existingKeys } = await client.apiKey.getMany({ query: { limit: 100 } });
   147	  const existingKeyNames = new Set(existingKeys.map((k) => k.name));
   148	
   149	  const allEnvs = ['master', ...TARGET_ENVIRONMENTS];
   150	  for (const envId of allEnvs) {
   151	    const tierLabel = envId === 'master' ? 'PRODUCTION' : envId.toUpperCase();
   152	    const keyName = `Zimmermann ${tierLabel} — Delivery`;
   153	
   154	    if (existingKeyNames.has(keyName)) {
   155	      log.skip(`API key '${keyName}' already exists`);
   156	      results.apiKeys.skipped.push(envId);
   157	      continue;
   158	    }
